 const cap=(n,a=0,b=100)=>Math.max(a,Math.min(b,n)),round=n=>Math.round(n*100)/100,bio=s=>Engine.biological(s),hash=(s,k)=>{let h=Math.imul((s.seed^k)>>>0,2654435761);return(h^(h>>>16))>>>0},god=id=>FaithLore.find(g=>g.id===id);
