 function finish(s,outcome){const f=ensure(s),a=f.active;if(!a)return;f.completed.push({id:a.id,outcome,age:s.age,year:WorldTimeline.year(s),path:a.path||'none'});f.active=null;f.nextEncounter=s.calendar.count+8}
