 function install(){for(const g of FaithLore){const C=(label,effect,success,faithPath)=>({label,effect,success,faithPath,risk:0});const stages=[['คำขอจากผู้มีตัวตน',g.request,[C('รับเควสต์และฟังเงื่อนไข',{wisdom:2},'คุณรับฟังคำขอ และกันเวลาในชีวิตไว้ให้สิ่งที่ยังไม่รู้ทั้งหมด','obey'),C('ขอสิทธิ์ตรวจผลที่จะตกกับเผ่าอื่น',{wisdom:2},'เทพยอมให้คุณตรวจสิ่งที่ผู้ร่วมศรัทธาอาจมองข้ามก่อนตอบคำบัญชา','reinterpret'),C('ปฏิเสธคำขอและใช้ชีวิตต่อ',{joy:1},'เทพรับรู้การปฏิเสธ ผู้ส่งสารจากไปและคุณยังรักษาทางเลือกของตน','refuse')]],['ราคาของการลงมือ',g.trial,[C('เตรียมพิธีตามคำบัญชา',{gold:-g.cost,health:-1,magic:3},'คุณเตรียมจุดเชื่อมและผู้ร่วมพิธีตามแบบเดิม แต่ผลต่อถิ่นอื่นยังรอคำตัดสินสุดท้ายของคุณ','obey'),C('ร่วมออกแบบทางที่เผ่าอื่นยังอยู่ได้',{wisdom:3,bond:2},'คุณใช้เวลาฟังผู้รับผลและแก้ขอบเขตพิธี แม้ผู้เคร่งบางส่วนไม่พอใจ','reinterpret'),C('ถอนตัวก่อนพิธีจะผูกถิ่นอื่น',{joy:-1,wisdom:1},'คุณแจ้งเหตุผลและหยุดส่วนที่ตนรับผิดชอบ ไม่มีผลพิธีจากการลงมือของคุณเกิดขึ้น','refuse')]],['สิ่งที่จะฝากไว้ในโลก',g.tension,[C(g.obedience,{magic:4,fame:2},g.result,'obey'),C(g.alternative,{wisdom:4,bond:3},g.alternateResult,'reinterpret'),C('หยุดพิธีและคืนสิทธิ์ตัดสินใจให้ผู้ได้รับผล',{joy:-1,wisdom:2},'คุณยุติพิธีในส่วนที่ตนเป็นจุดเชื่อม เทพรับรู้ว่าคุณเลือกไม่มอบอำนาจเหนือเผ่าอื่นให้คำบัญชานี้','refuse')]]];stages.forEach(([title,text,choices],faithStage)=>EVENTS.push({id:'faith-'+g.id+'-'+faithStage,title,text,choices,faithOnly:g.id,faithStage,min:18,once:true,certain:true,lifeOpportunity:true,ecology:true,scene:Ecology.profile(0).scene}))}}
